CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'public', status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reports (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT, photo_url TEXT, category TEXT NOT NULL, severity INTEGER NOT NULL CHECK (severity BETWEEN 1 AND 5), latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, status TEXT NOT NULL DEFAULT 'open', last_activity_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX reports_user_id_idx ON reports(user_id);
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY, report_id BIGINT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id), body TEXT NOT NULL, is_authority_comment BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX comments_report_id_idx ON comments(report_id);
CREATE TABLE likes (id BIGSERIAL PRIMARY KEY, report_id BIGINT NOT NULL REFERENCES reports(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT likes_report_user_unique UNIQUE(report_id,user_id));
CREATE TABLE authority_requests (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), organization_name TEXT NOT NULL, justification TEXT, status TEXT NOT NULL DEFAULT 'pending', reviewed_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
